    adcs_quat_t cur_n, tgt_n, q_rel;
    adcs_quat_t cur_conj;
    double angle, req, mar, cw;

    if ((current == NULL) || (target == NULL) || (required_rate == NULL) || (margin == NULL)) {
        if (required_rate != NULL) *required_rate = INFINITY;
        if (margin != NULL) *margin = -INFINITY;
        return ADCS_E_NULL;
    }

    *required_rate = INFINITY;
    *margin = -INFINITY;

    if ((adcs_quat_normalize(current, &cur_n) != ADCS_OK) ||
        (adcs_quat_normalize(target, &tgt_n) != ADCS_OK))
        return ADCS_E_RANGE;

    if ((!isfinite(duration)) || (duration <= 0.0) ||
        (!isfinite(max_rate)) || (max_rate < 0.0))
        return ADCS_E_RANGE;

    cur_conj = adcs_quat_conjugate(&cur_n);
    q_rel = adcs_quat_multiply(&tgt_n, &cur_conj);

    cw = fabs(q_rel.w);
    cw = ADCS_CLAMP(cw, 0.0, 1.0);
    angle = 2.0 * acos(cw);

    req = angle / duration;
    mar = max_rate - req;

    *required_rate = req;
    *margin = mar;
    return ADCS_OK;
}

